    size_t scan_position = search_from;
    size_t last_accept_position = RX_NO_POSITION;
    int forward_state = RX_FORWARD_START;

    if (search_from > subject_length) return 0;

    /* ---- FORWARD SCAN: where does a match end? ----------------------
     * One byte per iteration. The loop keeps the LAST accepting
     * position rather than stopping at the first, because `[a-z]+` can
     * always run further and the longest run is the answer wanted here.
     */
