/* D49: the give-up codes PROPAGATE rather than collapsing to -1.
 * Unreachable on this engine — a DFA artifact has no counter to
 * exhaust — but written uniformly on purpose: the contract of
 * rx_matchfn is one contract, and a wrapper that discards codes it
 * merely happens never to see is the shape that goes wrong when a
 * later engine shares this emitter. */
ptrdiff_t rx_match(const rx_ctx *ctx)
{
    // Initialized: gcc -O1 false maybe-uninitialized (pcrec K28).
    ptrdiff_t capture_spans[RX_NCAPS][2] = {{0}};
    int search_result = rx_search(ctx->subject, ctx->len, ctx->pos, capture_spans);
    if (search_result < 0) return (ptrdiff_t)search_result;
    // rx_search is a SEARCH and may report a match starting later in the
    // subject; this entry is ANCHORED, so anything that did not start
    // exactly at ctx->pos is not an answer to the question asked.
    if (search_result != 1 || (size_t)capture_spans[0][0] != ctx->pos) return -1;
    return capture_spans[0][1] - capture_spans[0][0];
}

ptrdiff_t rx_match_caps(const rx_ctx *ctx, ptrdiff_t (*capture_spans_out)[2])
{
    // Initialized: gcc -O1 false maybe-uninitialized (pcrec K28).
    ptrdiff_t capture_spans[RX_NCAPS][2] = {{0}};
    int search_result = rx_search(ctx->subject, ctx->len, ctx->pos, capture_spans);
    if (search_result < 0) return (ptrdiff_t)search_result;
    if (search_result != 1 || (size_t)capture_spans[0][0] != ctx->pos) return -1;
    if (capture_spans_out) {
        for (int slot = 0; slot < RX_NCAPS; slot++) {
            capture_spans_out[slot][0] = capture_spans[slot][0];
            capture_spans_out[slot][1] = capture_spans[slot][1];
        }
    }
    return capture_spans[0][1] - capture_spans[0][0];
}

/* byte encoding: one byte is one character, so the next boundary after
 * position is position + 1 and the subject is never read. */
size_t rx_next_pos(const unsigned char *subject, size_t subject_length, size_t position)
{
    (void)subject; (void)subject_length;
    return position + 1;
}

